const seedHistory={'Rice Bag 25kg':[16,18,17,20,19,18,21,17],'Cooking Oil 5L':[10,12,11,13,12,14,11,12],'Chicken Breast':[42,45,44,48,46,43,49,47],'Mozzarella 1kg':[9,10,8,11,12,9,10,11],'Tomato Crate':[25,28,27,30,29,26,31,28],'Burger Buns':[56,60,58,63,61,59,65,62]};
try{const existing=JSON.parse(localStorage.getItem('kitcheniq-history')||'null');if(!existing||typeof existing!=='object'||!Object.keys(existing).length)localStorage.setItem('kitcheniq-history',JSON.stringify(seedHistory));}catch{localStorage.setItem('kitcheniq-history',JSON.stringify(seedHistory));}
if(!document.getElementById('discountCards')){const holder=document.createElement('div');holder.id='discountCards';holder.hidden=true;document.body.appendChild(holder);}
window.addEventListener('load',()=>{const items=(()=>{try{return JSON.parse(localStorage.getItem('kitcheniq-items'))||[]}catch{return[]}})();const planning=document.getElementById('planningMetrics');const money=n=>`$${Number(n).toFixed(2)}`;if(planning&&items.length){const low=items.filter(i=>i.stock<=Math.ceil(i.demand*i.lead/7)).length,weekly=items.reduce((s,i)=>s+i.demand,0),value=items.reduce((s,i)=>s+i.stock*i.unit,0),buy=items.reduce((s,i)=>s+Math.max(1,Math.ceil(i.demand*2-i.stock)),0);planning.innerHTML=[['Weekly demand',weekly,'units / week'],['Recommended buy',buy,'units across items'],['At-risk items',low,'below reorder point'],['Inventory value',money(value),'current stock value']].map(x=>`<article class="metric"><div class="metric-label">${x[0]}</div><div class="metric-value">${x[1]}</div><div class="metric-note">${x[2]}</div></article>`).join('');}const historyView=document.getElementById('history');if(historyView&&!document.getElementById('historyInsight')){const box=document.createElement('div');box.id='historyInsight';box.className='history-intro';box.innerHTML='<div class="history-summary-card"><div class="muted">WHY THIS DATA MATTERS</div><div class="big">Demand pattern</div><div class="muted">Historical weekly demand is used by Stochastic Control to estimate average demand, variability, safety stock and the safer reorder point.</div></div><div class="history-summary-card"><div class="muted">HOW TO USE</div><div class="big">Add → compare → plan</div><div class="muted">Choose an item, review its weekly demand history, then add new weeks as actual restaurant sales arrive.</div></div>';const panel=historyView.querySelector('.panel');if(panel)panel.parentNode.insertBefore(box,panel);}});